                    <div class="w-10 h-10 rounded-full bg-[#C8FF00]/15 border-[0.5px] border-[#C8FF00]/30 flex items-center justify-center text-[#C8FF00]"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-users w-5 h-5" aria-hidden="true"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><path d="M16 3.128a4 4 0 0 1 0 7.744"></path><path d="M22 21v-2a4 4 0 0 0-3-3.87"></path><circle cx="9" cy="7" r="4"></circle></svg></div>
                    <h3 class="text-lg sm:text-xl font-bold font-arabic text-white">قادة المجتمع</h3>
